 "content": "from collections import deque


def transform(grid):
    """Color the 3x3-window interiors in each 1-region with its marker color."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    # Each 4-connected region of nonzero cells carries its own color marker.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            colors = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                if grid[y][x] not in (0, 1):
                    colors.append(grid[y][x])
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if not colors:
                continue
            color = colors[0]
            for y, x in cells:
                if grid[y][x] != 1 or y == 0 or x == 0 or y == h - 1 or x == w - 1:
                    continue
                if all(grid[yy][xx] != 0
                       for yy in range(y - 1, y + 2)
                       for xx in range(x - 1, x + 2)):
                    out[y][x] = color
    return out
